ClearAll["Global`*"]
W[x_, y_, z_] := {y - x*z, 2 y + x^2, z^2 + x*y}
dens[x_, y_, z_] := y^2*(x + 3)*(z + 2)
surface = x^2 + 3 y^2 + 2 z == 5; z1 = -2;
(* límites: se despeja en la superficie *)
Solve[surface /. {y -> 0, z -> z1}, x]   (* x entre -3 y 3 *)
x1 = -3; x2 = 3;
Solve[surface /. z -> z1, y]             (* y entre las dos ramas *)
y1 = -Sqrt[(9 - x^2)/3]; y2 = Sqrt[(9 - x^2)/3];
zs[x_, y_] = z /. Flatten[Solve[surface, z]]   (* la superficie como z = zs(x, y) *)
dS = Sqrt[1 + D[zs[x, y], x]^2 + D[zs[x, y], y]^2];
(* en Mathematica: NIntegrate[dS, {x, x1, x2}, {y, y1, y2}]. Aquí, la integral interior exacta y la exterior numérica *)
interior[x_] = Integrate[dS, {y, y1, y2}];
Area = NIntegrate[interior[x], {x, x1, x2}]

